-- GroomPro demo customer addresses. Upload to the GroomPro MySQL database or deploy through GoDaddy.
-- Only the reviewed fictional customer IDs and names match. Existing addresses are preserved.
-- Original address values are saved in ImportRecord before updating; repeat runs skip those records.
START TRANSACTION;
SET @groompro_demo_address_run = UUID();

INSERT INTO ImportRecord (id, tenantId, source, entityType, sourceId, targetId, payload, createdAt, updatedAt)
SELECT UUID(), c.tenantId, 'groompro-demo-addresses-v1', 'CUSTOMER', c.id, c.id,
  JSON_OBJECT('run', @groompro_demo_address_run, 'before', JSON_OBJECT('address1', c.address1, 'address2', c.address2, 'city', c.city, 'state', c.state, 'postalCode', c.postalCode),
    'street', d.street, 'unit', d.unit), CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)
FROM (
  SELECT CONVERT(0x636d76336b627a37383030303976356b7731766f77636a7a36 USING utf8mb4) AS sourceId, CONVERT(0x50494e USING utf8mb4) AS firstName, CONVERT(0x437573746f6d6572 USING utf8mb4) AS lastName, '200 South Main Street' AS street, NULL AS unit
  UNION ALL
  SELECT CONVERT(0x636d766a316f336173303033677635683465747567747a3638 USING utf8mb4), CONVERT(0x45646d756e646f USING utf8mb4), CONVERT(0x5468726565 USING utf8mb4), '200 Schlather Street', NULL
