) d
LEFT JOIN ImportRecord r ON CAST(r.sourceId AS BINARY) = CAST(d.sourceId AS BINARY)
  AND r.source = 'GroomPro Local Demo 2026' AND r.entityType = 'CUSTOMER'
  AND JSON_UNQUOTE(JSON_EXTRACT(r.payload, '$.preparedFixture')) = '52d79f0b28915f4c8a58bc2a360366238d9eb0a2fe3590433aac17fe4514aede'
JOIN Customer c ON (CAST(c.id AS BINARY) = CAST(d.sourceId AS BINARY) OR CAST(c.importSourceId AS BINARY) = CAST(d.sourceId AS BINARY) OR (c.id = r.targetId AND c.tenantId = r.tenantId))
  AND CAST(LOWER(TRIM(c.firstName)) AS BINARY) = CAST(LOWER(TRIM(d.firstName)) AS BINARY)
  AND CAST(LOWER(TRIM(c.lastName)) AS BINARY) = CAST(LOWER(TRIM(d.lastName)) AS BINARY)
WHERE COALESCE(TRIM(c.address1), '') = '' AND COALESCE(TRIM(c.address2), '') = ''
  AND COALESCE(TRIM(c.city), '') = '' AND COALESCE(TRIM(c.state), '') = '' AND COALESCE(TRIM(c.postalCode), '') = ''
ON DUPLICATE KEY UPDATE id = ImportRecord.id;

UPDATE Customer c
JOIN ImportRecord b ON b.tenantId = c.tenantId AND b.source = 'groompro-demo-addresses-v1'
  AND b.entityType = 'CUSTOMER' AND b.sourceId = c.id AND b.targetId = c.id
  AND CAST(JSON_UNQUOTE(JSON_EXTRACT(b.payload, '$.run')) AS BINARY) = CAST(@groompro_demo_address_run AS BINARY)
SET c.address1 = JSON_UNQUOTE(JSON_EXTRACT(b.payload, '$.street')),
    c.address2 = IF(JSON_TYPE(JSON_EXTRACT(b.payload, '$.unit')) = 'NULL', NULL, JSON_UNQUOTE(JSON_EXTRACT(b.payload, '$.unit'))),
    c.city = 'Cibolo', c.state = 'TX', c.postalCode = '78108', c.updatedAt = CURRENT_TIMESTAMP(3)
WHERE CAST(c.address1 AS BINARY) <=> CAST(IF(JSON_TYPE(JSON_EXTRACT(b.payload, '$.before.address1')) = 'NULL', NULL, JSON_UNQUOTE(JSON_EXTRACT(b.payload, '$.before.address1'))) AS BINARY)
  AND CAST(c.address2 AS BINARY) <=> CAST(IF(JSON_TYPE(JSON_EXTRACT(b.payload, '$.before.address2')) = 'NULL', NULL, JSON_UNQUOTE(JSON_EXTRACT(b.payload, '$.before.address2'))) AS BINARY)
  AND CAST(c.city AS BINARY) <=> CAST(IF(JSON_TYPE(JSON_EXTRACT(b.payload, '$.before.city')) = 'NULL', NULL, JSON_UNQUOTE(JSON_EXTRACT(b.payload, '$.before.city'))) AS BINARY)
  AND CAST(c.state AS BINARY) <=> CAST(IF(JSON_TYPE(JSON_EXTRACT(b.payload, '$.before.state')) = 'NULL', NULL, JSON_UNQUOTE(JSON_EXTRACT(b.payload, '$.before.state'))) AS BINARY)
  AND CAST(c.postalCode AS BINARY) <=> CAST(IF(JSON_TYPE(JSON_EXTRACT(b.payload, '$.before.postalCode')) = 'NULL', NULL, JSON_UNQUOTE(JSON_EXTRACT(b.payload, '$.before.postalCode'))) AS BINARY);
COMMIT;
